import{c as i,Q as a,j as t,m as e}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"【保存推奨】Claude Skills 67選──ポテンシャルを100%引き出し\\"開発チーム化\\"する方法","description":"","frontmatter":{"url":"https://x.com/ClaudeCode_love/status/2045082723027751079","title":"【保存推奨】Claude Skills 67選──ポテンシャルを100%引き出し\\"開発チーム化\\"する方法","author":"ClaudeCode_love","archived":"2026-06-02T00:00:00.000Z","handle":"@ClaudeCode_love","published":"2026-04-17T00:00:00.000Z","stats":"2178 likes · 198 retweets · 5483 bookmarks · 1576802 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-04-17-@ClaudeCode_love-751079.md","filePath":"research/tweets/2026-04-17-@ClaudeCode_love-751079.md","lastUpdated":1780990164000}'),l={name:"research/tweets/2026-04-17-@ClaudeCode_love-751079.md"};function n(p,s,o,r,d,h){return a(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="【保存推奨】claude-skills-67選──ポテンシャルを100-引き出し-開発チーム化-する方法-—-claudecode-love" tabindex="-1">【保存推奨】Claude Skills 67選──ポテンシャルを100%引き出し&quot;開発チーム化&quot;する方法 — @ClaudeCode_love <a class="header-anchor" href="#【保存推奨】claude-skills-67選──ポテンシャルを100-引き出し-開発チーム化-する方法-—-claudecode-love" aria-label="Permalink to &quot;【保存推奨】Claude Skills 67選──ポテンシャルを100%引き出し&quot;開発チーム化&quot;する方法 — @ClaudeCode_love&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ClaudeCode_love/status/2045082723027751079" target="_blank" rel="noreferrer">https://x.com/ClaudeCode_love/status/2045082723027751079</a><strong>作者</strong>：ClaudeCode_love（@ClaudeCode_love） <strong>發布日期</strong>：2026-04-17 <strong>收錄日期</strong>：2026-06-02 <strong>類型</strong>：Twitter Article <strong>統計</strong>：2178 likes · 198 retweets · 5483 bookmarks · 1576802 views <strong>原文來源</strong>：@polydao 帖子（124 萬 views）</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>皆さんSkillsって多すぎてどれを入れればいいか迷いますよね😱 大丈夫です。マジでこの記事で全部解決します！最後まで見ていただけたら本当にあなたのClaudeが10倍頭良くなることをお約束します！🔥</p><p>Claude,ClaudeCode普段使っててこんな悩みありませんか？</p><p>[圖 1]</p><p>・Claude Codeを使ってるけど、毎回同じ説明を繰り返してる ・Skillsという機能があるのは知ってるけど、何を入れればいいのかわからない ・設計→開発→テスト→ドキュメントの流れを自動化したい ・Claude Codeを「ただのコード補完」以上に使いこなしたい</p><p>今、海外のAI・クリプト領域で影響力のあるMr. Buzzoni氏（@polydao）が投稿した「Claude Skills 67選」が124万ビューの大バズ中😳 今回はその内容をわかりやすく噛み砕いて解説します👇</p><p>元ポスト：<a href="https://x.com/polydao/status/2044317956893471081" target="_blank" rel="noreferrer">https://x.com/polydao/status/2044317956893471081</a></p><h2 id="そもそも-claude-skills-とは何か" tabindex="-1">そもそも Claude Skills とは何か <a class="header-anchor" href="#そもそも-claude-skills-とは何か" aria-label="Permalink to &quot;そもそも Claude Skills とは何か&quot;">​</a></h2><p>[圖 2]</p><p>ほとんどの人はClaude Codeを「普通に指示するだけで」使っています。質問して、回答を得て、それで終わり。</p><p>でもClaude Codeには「Skills」という仕組みがあり、これを使うとClaude Codeは設計者・レビュアー・デバッガー・ドキュメントライターを兼ねた開発チームとして機能します。</p><p>Skillとは、SKILL.mdファイルが入ったフォルダのことです。このファイルには「特定の作業をどうやるか」がステップバイステップで書かれています。制約、例、ヘルパースクリプト、テンプレートも含められます。</p><p>[圖 3]</p><p>つまり、毎回セッションのたびに「こうやって、ああやって」と説明する必要がなくなります。一度Skillとしてインストールすれば、以降はずっと再利用できます。</p><p>インストールコマンド：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [リポジトリ/パス]</span></span></code></pre></div><p>[圖 4]</p><p>主要なSkillsのソース：</p><ul><li><strong>Anthropic公式</strong>：github.com/anthropics/skills</li><li><strong>Matt Pocock（15,000スター超）</strong>：github.com/mattpocock/skills</li><li><strong>コミュニティマーケットプレイス（66,000以上のSkills）</strong>：skillsmp.com</li></ul><h2 id="meta-skills-──-まず最初に入れるべき「スキルを作るスキル」" tabindex="-1">Meta Skills ── まず最初に入れるべき「スキルを作るスキル」 <a class="header-anchor" href="#meta-skills-──-まず最初に入れるべき「スキルを作るスキル」" aria-label="Permalink to &quot;Meta Skills ── まず最初に入れるべき「スキルを作るスキル」&quot;">​</a></h2><p>[圖 5]</p><p>他のすべてのSkillの土台になるのがMeta Skillsです。</p><p><strong>Skill Creator</strong>（最重要）</p><p>[圖 6]</p><p>あなたのタスクでClaudeをベンチマークし、実際の実行結果に基づいて新しいSkillの作成と改善を支援します。 使い方：ワークフローを箇条書きで説明 → SKILL.md案を提案させる → 3〜5回テストして失敗を分析 → 改善させる</p><p>リンク：github.com/anthropics/skills/tree/main/skills/skill-creator</p><p><strong>Write a Skill</strong></p><p>適切な構造・段階的開示・バンドルリソースを備えたSkillの書き方をガイドします。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/write-a-skill</span></span></code></pre></div><p><strong>Find Skills</strong></p><p>SkillsMPなどの公開マーケットプレイスから、あなたのユースケースに合ったSkillを検索します。新しいSkillを書く前に、まず既存のものを探してフォークするのが鉄則です。 マーケットプレイス：skillsmp.com</p><h2 id="planning-design-──-「間違ったものを作る」を防ぐスキル群" tabindex="-1">Planning &amp; Design ── 「間違ったものを作る」を防ぐスキル群 <a class="header-anchor" href="#planning-design-──-「間違ったものを作る」を防ぐスキル群" aria-label="Permalink to &quot;Planning &amp; Design ── 「間違ったものを作る」を防ぐスキル群&quot;">​</a></h2><p>[圖 7]</p><p>設計段階のSkillsは、開発後の手戻りの80%を防ぎます。</p><p>[圖 8]</p><p><strong>Grill Me</strong></p><p>Claudeが容赦なく質問を投げかけ、意思決定ツリーの全分岐が解決するまで追い詰めます。新機能、リファクタ、リスクの高いマイグレーションに使います。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/grill-me</span></span></code></pre></div><p><strong>Write a PRD</strong></p><p>インタラクティブなインタビュー、コードベース探索、モジュール設計を通じてPRD（プロダクト要件定義書）を作成し、GitHubイシューとして登録します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/write-a-prd</span></span></code></pre></div><p><strong>PRD to Plan</strong></p><p>[圖 9]</p><p>PRDをトレーサーバレット方式の垂直スライスで多段階の実装計画に変換します。統合リスクを実際に下げる順序を出してくれます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/prd-to-plan</span></span></code></pre></div><p><strong>PRD to Issues</strong></p><p>PRDを独立して着手可能なGitHubイシューに分解します。垂直スライスとブロッキング関係付き。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/prd-to-issues</span></span></code></pre></div><p><strong>Design an Interface</strong></p><p>並列サブエージェントを使い、1つのモジュールに対して3〜5個の根本的に異なるインターフェース設計を生成します。異なるトレードオフを持つ複数の選択肢が得られます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/design-an-interface</span></span></code></pre></div><p><strong>Request Refactor Plan</strong></p><p>ユーザーインタビューを通じて小さなコミット単位の詳細なリファクタ計画を作成し、GitHubイシューとして登録します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/request-refactor-plan</span></span></code></pre></div><h2 id="code-development-──-claude-codeを「規律ある開発パートナー」に変える" tabindex="-1">Code Development ── Claude Codeを「規律ある開発パートナー」に変える <a class="header-anchor" href="#code-development-──-claude-codeを「規律ある開発パートナー」に変える" aria-label="Permalink to &quot;Code Development ── Claude Codeを「規律ある開発パートナー」に変える&quot;">​</a></h2><p>[圖 10]</p><p><strong>TDD</strong></p><p>厳格なテストファースト・red-green-refactorループを強制します。まず失敗するテスト → それを通す最小のコード → テストを維持したままリファクタ。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/tdd</span></span></code></pre></div><p><strong>Triage Issue</strong></p><p>「なぜ壊れてるのか全くわからない」時のスキル。コードベースを探索して根本原因を特定し、TDDベースの修正計画をGitHubイシューとして登録します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/triage-issue</span></span></code></pre></div><p><strong>QA</strong></p><p>機能に対するフルQAパスを実行。PR前に毎回使うことで、エッジケースを洗い出してリグレッションなしで出荷できます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/qa</span></span></code></pre></div><p><strong>Improve Codebase Architecture</strong></p><p>コードベースのアーキテクチャ改善ポイントを探索。ホットスポットの特定、2〜3のリファクタ戦略の提案、各戦略のリスク・工数・インパクトの詳細を出してくれます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/improve-codebase-architecture</span></span></code></pre></div><p><strong>Systematic Debugging</strong></p><p>「とりあえず変えてみる」を禁止する4段階デバッグ方法論。再現 → 最小の失敗テスト作成 → 根本原因の絞り込み → 単一修正 → テスト検証。</p><p>リンク：github.com/obra/superpowers/tree/main/skills/systematic-debugging</p><p><strong>Auto-Commit Messages</strong></p><p>ステージされたdiffを読み、type・scope・bodyを含むConventional Commitメッセージを自動生成。</p><p>リンク：github.com/anthropics/skills/tree/main/skills/auto-commit</p><p><strong>Code Review</strong></p><p>セキュリティ・パフォーマンス・エラーハンドリング・アーキテクチャの体系的レビュー。「セキュリティ重視レビュー」「パフォーマンス重視レビュー」など焦点を指定できます。</p><p>リンク：github.com/anthropics/skills</p><p><strong>Superpowers</strong></p><p>TDD・デバッグ・リファクタリング・実行の実戦テスト済みSkill一式。デフォルトの「エンジニアリング脳」レイヤーとして使えます。</p><p>リンク：github.com/obra/superpowers</p><h2 id="tooling-setup-──-「一度やったら二度と触らない」系スキル" tabindex="-1">Tooling &amp; Setup ── 「一度やったら二度と触らない」系スキル <a class="header-anchor" href="#tooling-setup-──-「一度やったら二度と触らない」系スキル" aria-label="Permalink to &quot;Tooling &amp; Setup ── 「一度やったら二度と触らない」系スキル&quot;">​</a></h2><p>[圖 11]</p><p><strong>Setup Pre-Commit</strong></p><p>Husky pre-commitフック + lint-staged + Prettier + 型チェック + テストをセットアップ。新しいリポジトリごとに実行すべき。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/setup-pre-commit</span></span></code></pre></div><p><strong>Git Guardrails for Claude Code</strong></p><p>push、reset --hard、cleanなどの危険なgitコマンドを実行前にブロックするフックを設定。本番リポジトリでClaude Codeを使うなら必須のセーフティネット。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/git-guardrails-claude-code</span></span></code></pre></div><p><strong>Dependency Auditor</strong></p><p>package.jsonの古い・脆弱・放棄されたパッケージをスキャンし、優先度付きの修正リストを出力。</p><p>リンク：github.com/ComposioHQ/awesome-claude-skills</p><h2 id="writing-knowledge-──-ドキュメント・記事・用語定義" tabindex="-1">Writing &amp; Knowledge ── ドキュメント・記事・用語定義 <a class="header-anchor" href="#writing-knowledge-──-ドキュメント・記事・用語定義" aria-label="Permalink to &quot;Writing &amp; Knowledge ── ドキュメント・記事・用語定義&quot;">​</a></h2><p>[圖 12]</p><p><strong>Edit Article</strong></p><p>「文法修正」ではなく、議論の再構成・不要部分のカット・各セクションの論点を研ぎ澄ませるレベルの編集を行います。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/edit-article</span></span></code></pre></div><p><strong>Ubiquitous Language</strong></p><p>DDD（ドメイン駆動設計）スタイルのユビキタス言語用語集を会話から抽出。チーム内でコードベース・ドキュメント・会話が同じ言葉を共有できます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/ubiquitous-language</span></span></code></pre></div><p><strong>API Documentation Generator</strong></p><p>ルートを読み取り、例・エラーコード・認証要件付きのOpenAPI/Swaggerドキュメントを生成。30秒で完了。</p><p>リンク：github.com/ComposioHQ/awesome-claude-skills</p><p><strong>Obsidian Vault</strong></p><p>Obsidian Vaultの検索・作成・管理をwikilinksとインデックスノート付きで行います。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mattpocock/skills/obsidian-vault</span></span></code></pre></div><h2 id="ui-design-frontend-──-デザイン系スキル" tabindex="-1">UI / Design / Frontend ── デザイン系スキル <a class="header-anchor" href="#ui-design-frontend-──-デザイン系スキル" aria-label="Permalink to &quot;UI / Design / Frontend ── デザイン系スキル&quot;">​</a></h2><p>[圖 13]</p><ul><li><strong>Frontend Design</strong>：モダンでクリーンなUI生成をガイド — github.com/anthropics/skills/tree/main/skills/frontend-design</li><li><strong>Theme Factory</strong>：テキストプロンプト1つから完全なカラーパレットとテーマを生成 — github.com/anthropics/skills/tree/main/skills/theme-factory</li><li><strong>Web Artifacts Builder</strong>：自然言語からインタラクティブなダッシュボード・計算機・ツールを構築 — github.com/anthropics/skills/tree/main/skills/web-artifacts-builder</li><li><strong>Brand Guidelines</strong>：全ての新しいコンポーネントにブランドシステムを強制適用 — github.com/anthropics/skills/tree/main/skills/brand-guidelines</li></ul><h2 id="business-sales-marketing-──-ビジネス系スキル" tabindex="-1">Business / Sales / Marketing ── ビジネス系スキル <a class="header-anchor" href="#business-sales-marketing-──-ビジネス系スキル" aria-label="Permalink to &quot;Business / Sales / Marketing ── ビジネス系スキル&quot;">​</a></h2><p>[圖 14]</p><ul><li><strong>Stripe Integration</strong>：安全な決済フロー・Webhook・サブスクリプションのセットアップ</li><li><strong>Marketing Skills</strong>：CRO・コピーライティング・メールフローなど20以上のスキル集 — github.com/coreyhaines31/marketingskills</li><li><strong>Claude SEO</strong>：テクニカルSEO監査、スキーマ、オンページ最適化 — github.com/AgriciDaniel/claude-seo</li><li><strong>Domain Name Brainstormer</strong>：プロダクト名生成とドメイン空き状況チェック</li></ul><h2 id="office-documents-──-オフィス系スキル" tabindex="-1">Office &amp; Documents ── オフィス系スキル <a class="header-anchor" href="#office-documents-──-オフィス系スキル" aria-label="Permalink to &quot;Office &amp; Documents ── オフィス系スキル&quot;">​</a></h2><p>[圖 15]</p><p><strong>PDF / DOCX / PPTX / XLSX</strong>：テーブル抽出・フォーム入力・PDF結合、Wordの変更履歴付き編集、スライドデッキの作成・編集、平文からの数式・ピボットテーブル・チャート作成。全てAnthropic公式から提供。</p><p>リンク：github.com/anthropics/skills/tree/main/skills/</p><p><strong>Doc Co-Authoring</strong>：あなたとClaudeのリアルタイム共同執筆。</p><h2 id="multi-agent-──-マルチエージェント系スキル" tabindex="-1">Multi-Agent ── マルチエージェント系スキル <a class="header-anchor" href="#multi-agent-──-マルチエージェント系スキル" aria-label="Permalink to &quot;Multi-Agent ── マルチエージェント系スキル&quot;">​</a></h2><p><strong>Stochastic Multi-Agent Consensus</strong>：多数のサブエージェントを生成して同じ問題を解かせ、回答を集約。戦略判断・アーキテクチャ選択・リスク分析に。</p><p>リンク：github.com/hungv47/meta-skills</p><p><strong>Model-chat（Debate）</strong>：複数のClaudeインスタンスをディベートさせてアイデアをストレステスト。2〜3の大きな賭けの間で迷っている時に。</p><p>リンク：github.com/tommasinigiovanni/conclave</p><p><strong>Firecrawl Skill</strong>：一般的なスクレイパーをブロックする複雑なサイトから構造化データを抽出。</p><p>リンク：github.com/mendableai/firecrawl</p><h2 id="おすすめの導入順序" tabindex="-1">おすすめの導入順序 <a class="header-anchor" href="#おすすめの導入順序" aria-label="Permalink to &quot;おすすめの導入順序&quot;">​</a></h2><p>[圖 16]</p><ol><li><strong>まずMeta Skillsから</strong> ── Write a SkillとSkill Creatorを入れて、Skillsの作成と修正ができる状態にする</li><li><strong>Planning系を追加</strong> ── Grill Me、Write a PRD、PRD to Plan、PRD to Issues、Design an Interface。これで手戻りの80%を防止</li><li><strong>コードの安全装置</strong> ── Git Guardrails、Setup Pre-Commit、TDD、Systematic Debugging、Triage Issue。全リポジトリに入れる</li><li><strong>Superpowersをベースレイヤーとして追加</strong> ── github.com/obra/superpowers</li><li><strong>ビジネス系スキルを上に重ねる</strong> ── Marketing Skills、Claude SEO、Lead Research、Content Researcher</li><li><strong>SkillsMPで穴を埋める</strong> ── skillsmp.com で新しい課題に当たったら、作る前にまず検索</li></ol><p>[圖 17]</p><p>重要なのは、Skillsは「全部入れる」ものではなく「必要なものを選んで入れる」ものだということです。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：日文版「Claude Skills 67 選」精選指南，系統化分類 9 類別 Skills（Meta/Planning/Code/Tooling/Writing/UI/Business/Office/Multi-Agent）並提供推薦導入順序，是 Skills 生態系的高品質索引。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Skills 定義</strong>：SKILL.md 檔案的資料夾，包含 step-by-step 指引 + 約束 + 範例 + 腳本；<code>npx skills@latest add</code> 為標準安裝指令</li><li><strong>Meta Skills 優先</strong>：Skill Creator + Write a Skill 先裝，讓 Claude 能幫你創建和改善 Skills 本身</li><li><strong>Planning 防手戻り 80%</strong>：Grill Me（無情提問）→ Write a PRD → PRD to Plan（tracer bullet 垂直切片）→ PRD to Issues</li><li><strong>安全裝置不可少</strong>：Git Guardrails（阻斷 push/reset --hard/clean）+ Setup Pre-Commit + TDD + Systematic Debugging</li><li><strong>推薦導入順序</strong>：Meta → Planning → Safety → Superpowers base → Business → SkillsMP 填空</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>原帖 @polydao：124 萬 views；本文：157 萬 views / 5483 bookmarks</li><li>Skills 來源：Anthropic 官方（github.com/anthropics/skills）、Matt Pocock（15,000+ stars）、skillsmp.com（66,000+ Skills）</li><li>安裝指令：<code>npx skills@latest add [repo/path]</code></li><li>Superpowers：github.com/obra/superpowers（TDD/debug/refactor/exec 一式）</li><li>Multi-Agent consensus：github.com/hungv47/meta-skills</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>本文是 @polydao 原帖的日文解說整理，originality 有限，但分類架構和導入順序的附加價值顯著</li><li>skillsmp.com 的 66,000+ Skills 數量令人印象深刻，但品質參差；「先搜尋再自製」的鐵則是重要的工作流規範</li><li>Systematic Debugging 4 段論（重現 → 最小失敗測試 → 根因縮小 → 單一修正 → 驗證）與現有 workspace R3/R9 規則高度一致</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>npx 安裝指令直接可用，導入順序清晰，多個 Skills 可強化現有 .claude/skills/</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>系統化分類 + 導入順序有附加價值，但本質是 @polydao 帖子的日文解說</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>124 萬 views 原帖背書，具體安裝指令可驗證，來源可靠</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>每個 Skill 有用途說明和安裝指令，分類架構合理</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Skills 生態系適用所有 Claude Code 用戶</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.8/10</strong></td><td>9×0.3+7×0.2+7×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：npx skills@latest 安裝流程 + skillsmp.com 資源 + 導入順序可直接強化現有 .claude/skills/ 策略，特別是 Meta Skills 先裝的哲學與現有 harness 設計一致。</p>',144)])])}const c=i(l,[["render",n]]);export{g as __pageData,c as default}